Method.Implementation:
	 #dim status as %Status
	 set status = $$$OK
	 $$$TRACE("Inside OnMessage method")	 

	 do ..JavaGateway.%Import(..JarFile) 	 

	 try{
		set ..objCdrTuxService = ##class(org.ihc.itf.cdr.CdrMmiUpdate).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService,..LockService,..UnlockService,..CDRMaxRetries,..RetryTimeoutSeconds)		
	 }catch err{
		$$$TRACE("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	    set status=$$$ERROR(" Exception while initializing Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)

	 }

	 try {		 
		set result = ..objCdrTuxService.updateMMI(pRequest.RawContent)
		$$$TRACE("Call Response: " _ result)		
		set pResponse = ##class(Ens.StringResponse).%New()  
 		set pResponse.StringValue = result 		
	 } catch err {	 
	 	$$$TRACE("Exception in calling CheckMmiUpdate; AsSystemError is: " _err.AsSystemError() _ ";$ZERROR: " _ $ZERROR _ ";ErrName: " _ $ZCVT(err.Name,"O","HTML")_ "; ErrData: " _ err.Data _ "; ErrCode:" _ err.Code _ "ErrLocation:" _ err.Location)	    

	    set status = $$$ERROR("Exception in calling updateMMI " _ err.Data)		    	     	 
		set errText = $SYSTEM.Status.GetOneErrorText(status)
	    if errText["CONNECTIONERROR"{		   
		   set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError($CLASSNAME(),errText)
	    }	    
	    if errText["RESEND"{
		   set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError($CLASSNAME(),errText)
	    }
	    if errText["DATAERROR"{
		   set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError($CLASSNAME(),errText)
	    }
	    if errText["SHUTDOWN"{
		   set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError($CLASSNAME(),errText)
	    }
	    if errText["is locked"{
		   set status = ##class(IHC.ITF.ITFCOMMON.Utility).SkipMsgError($CLASSNAME(),errText)
	    }
	 }

	 try {		
		if $IsObject(..objCdrTuxService) {
			$$$TRACE("Disconnecting from CDR Tuxedo service...")			
			set ..objCdrTuxService = $$$NULLOREF
		}
	 } catch {
		set tSC = $$$EnsSystemError
	 }
	 return status
